/**
 * Process-global pub/sub bus for session metadata changes.
 *
 * Titles used to be pull-only: `GET /api/sessions` was the one and only way
 * a browser could learn a conversation's name. That was fine for the
 * synchronous renames, but the real title is generated by an LLM *after* the
 * response has finished streaming, so the client (which refreshed its session
 * list once at turn end, plus once more on a 2s timer) regularly stopped
 * listening before the write landed — the sidebar and tab title then stayed
 * stale until a full page reload.
 *
 * The fix is push, not a longer guess: `renameSession()` emits here, the SSE
 * route (`app/api/sessions/events/route.ts`) streams the event to every open
 * tab, and the frontend patches the one row it names. Because the emit lives
 * inside `renameSession` itself, *every* rename path is covered — the
 * synchronous fallback title, the background LLM upgrade, and `/title` —
 * without any of them having to remember to announce itself.
 *
 * Design notes:
 * - This is a singleton stashed on `globalThis` so Next.js's dev HMR (and
 *   separate route-handler module instances) can't end up with a second bus,
 *   which would silently drop every event. Same trick as `mcp/events.ts`.
 * - Listeners are called synchronously, each wrapped in try/catch so a
 *   misbehaving subscriber (a dying SSE stream) can't break the write path
 *   that emitted the event.
 * - `subscribe` returns an unsubscribe function so route handlers can clean
 *   up on `request.signal.aborted` without juggling indexes.
 *
 * Server-side only — `history.ts` imports this, and that module owns the
 * SQLite handle.
 */

export type SessionEvent = {
  kind: 'renamed';
  sessionId: number;
  /** The title exactly as committed — no further validation by consumers. */
  name: string;
};

type Listener = (event: SessionEvent) => void;

interface SessionEventBus {
  listeners: Set<Listener>;
}

const GLOBAL_KEY = '__sessionEventBus';

function getBus(): SessionEventBus {
  const g = globalThis as unknown as Record<string, unknown>;
  let bus = g[GLOBAL_KEY] as SessionEventBus | undefined;
  if (!bus) {
    bus = { listeners: new Set() };
    g[GLOBAL_KEY] = bus;
  }
  return bus;
}

/**
 * Subscribe to session events. Returns an unsubscribe function. Safe to call
 * from any server-side module; this file must not be imported by client code
 * (it pulls in nothing itself, but its only producer is the SQLite layer).
 */
export function subscribeSessionEvents(fn: Listener): () => void {
  const bus = getBus();
  bus.listeners.add(fn);
  return () => {
    bus.listeners.delete(fn);
  };
}

/**
 * Fire an event to all current subscribers. Failures are isolated per
 * listener so one broken stream can't stop delivery to the rest. Never throws
 * — callers are persistence functions that must not fail on a UI concern.
 */
export function emitSessionEvent(event: SessionEvent): void {
  for (const fn of getBus().listeners) {
    try {
      fn(event);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      console.error(`[session-events] listener threw: ${message}`);
    }
  }
}
